        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * Whole fiscal years elapsed since the owner registered, or 0 when the registration date
     * is unknown. A new owner registers in the current fiscal year, so its tenure is 0.
     */

